INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Integration > Software
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Software in ein IT-System integriert werden, ohne die Abhängigkeiten zu anderen Programmen zu berücksichtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber führt oft zu Fehlern"}, {"text": "Nein", "correct": false, "because": "Abhängigkeiten sind kritisch, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Integration von Software immer ohne Auswirkungen auf die bestehende Systemleistung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Neue Software kann Ressourcen belasten"}, {"text": "Ja", "correct": false, "because": "Leistungseinflüsse sind häufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Softwarekomponenten eines Systems dieselbe Programmiersprache verwenden, um integriert zu werden?', 2, '[{"text": "Nein", "correct": true, "because": "Interoperabilität durch Schnittstellen möglich"}, {"text": "Ja", "correct": false, "because": "Heterogene Systeme sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Softwarelösungen ohne Testphase direkt in ein produktives System integriert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Möglich, aber riskant und unsicher"}, {"text": "Nein", "correct": false, "because": "Tests sind Best Practice, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Integration von Software unabhängig von der Hardwarekonfiguration eines Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Hardwareanforderungen beeinflussen Software"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist entscheidend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist vor der Integration neuer Software in ein bestehendes System unerlässlich?', 3, '[{"text": "Überprüfung der Systemanforderungen", "correct": true, "because": "Stellt Kompatibilität sicher"}, {"text": "Erstellung eines Marketingplans", "correct": false, "because": "Irrelevant für Integration"}, {"text": "Änderung der Benutzeroberfläche", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird häufig verwendet, um Softwarekomponenten über ein Netzwerk zu integrieren?', 2, '[{"text": "REST", "correct": true, "because": "Weit verbreitet für API-Integration"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe, nicht Software"}, {"text": "FTP", "correct": false, "because": "Für Dateiübertragung, nicht Integration"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Softwareintegration in einem IT-System?', 2, '[{"text": "Nahtlose Zusammenarbeit der Komponenten", "correct": true, "because": "Gewährleistet Funktionalität"}, {"text": "Reduktion der Entwicklungszeit", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Erhöhung der Hardwarekosten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler tritt oft bei der Integration von Software auf?', 3, '[{"text": "Inkompatible Schnittstellen", "correct": true, "because": "Verhindert Kommunikation"}, {"text": "Zu schnelle Installation", "correct": false, "because": "Kein Integrationsproblem"}, {"text": "Fehlende Benutzeranmeldung", "correct": false, "because": "Späterer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird typischerweise zur Verwaltung von Softwareintegration verwendet?', 2, '[{"text": "Docker", "correct": true, "because": "Ermöglicht Container-basierte Integration"}, {"text": "Excel", "correct": false, "because": "Für Daten, nicht Integration"}, {"text": "Notepad", "correct": false, "because": "Einfacher Editor, ungeeignet"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte müssen bei der Integration von Software berücksichtigt werden?', 4, '[{"text": "Kompatibilität mit bestehender Software", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Sicherheitsanforderungen", "correct": true, "because": "Schutz vor Schwachstellen"}, {"text": "Datenformate", "correct": true, "because": "Für Kommunikation essenziell"}, {"text": "Farbschema der Software", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Softwareintegration auftreten?', 3, '[{"text": "Versionskonflikte", "correct": true, "because": "Unterschiedliche Softwarestände"}, {"text": "Fehlende Schnittstellen", "correct": true, "because": "Blockiert Interaktion"}, {"text": "Performance-Einbußen", "correct": true, "because": "Zusätzliche Belastung"}, {"text": "Schnellere Benutzerakzeptanz", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen die Integration von Software?', 4, '[{"text": "APIs", "correct": true, "because": "Ermöglichen standardisierte Kommunikation"}, {"text": "Middleware", "correct": true, "because": "Vermittelt zwischen Systemen"}, {"text": "Webhooks", "correct": true, "because": "Ereignisgesteuerte Integration"}, {"text": "Betriebssystem-Design", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Softwareintegration typischerweise erforderlich?', 3, '[{"text": "Testen der Schnittstellen", "correct": true, "because": "Stellt Funktion sicher"}, {"text": "Anpassung der Konfiguration", "correct": true, "because": "Für Kompatibilität"}, {"text": "Dokumentation der Integration", "correct": true, "because": "Für Nachverfolgbarkeit"}, {"text": "Änderung der Hardware", "correct": false, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine erfolgreiche Softwareintegration?', 3, '[{"text": "Verbesserte Effizienz", "correct": true, "because": "Prozesse werden optimiert"}, {"text": "Kostensenkung", "correct": true, "because": "Weniger manuelle Arbeit"}, {"text": "Erhöhte Datenkonsistenz", "correct": true, "because": "Systeme teilen Informationen"}, {"text": "Geringere Sicherheitsanforderungen", "correct": false, "because": "Sicherheit bleibt wichtig"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Softwareintegration erfordert oft Anpassungen an bestehenden Systemen. b) Alle Software kann ohne Änderung integriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anpassung ja, universelle Integration nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Integration von Software kann die Wartungskosten erhöhen. b) Softwareintegration ist nur bei Neuinstallationen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, Integration auch später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) APIs sind eine gängige Methode zur Softwareintegration. b) Integrationstests sind überflüssig, wenn die Software funktioniert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "APIs ja, Tests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Softwareintegration kann zu Datenverlust führen, wenn schlecht geplant. b) Jede Softwareintegration erfordert einen Systemneustart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenverlust ja, Neustart nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine erfolgreiche Softwareintegration verbessert die Systemfunktionalität. b) Hardware hat keinen Einfluss auf die Softwareintegration.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktionalität ja, Hardware relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

